import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        int[] c = new int[n];
        int mx = 0;
        for (int i = 0; i < n; i++) mx = Math.max(mx, c[i] = nextInt());
        int[] freq = new int[mx + 1];
        for (int x : c) freq[x]++;
        // Keep the k most frequent categories, delete everything else.
        Arrays.sort(freq);
        long kept = 0;
        for (int i = 0; i < k && i <= mx; i++) kept += freq[mx - i];
        System.out.println(n - kept);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	c := make([]int, n)
	mx := 0
	for i := range c {
		c[i] = int(nextInt())
		mx = max(mx, c[i])
	}
	freq := make([]int, mx+1)
	for _, x := range c {
		freq[x]++
	}
	// Keep the k most frequent categories, delete everything else.
	slices.Sort(freq)
	slices.Reverse(freq)
	kept := 0
	for i := 0; i < k && i <= mx; i++ {
		kept += freq[i]
	}
	fmt.Println(n - kept)
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
